// Reusable renderers for the autogenerated Noir interface stubs that wrap
// `AuthRegistry` and `PublicChecks` external calls.
//
// Consumed by:
//   - `../scripts/generate_interfaces.ts` — the CLI that writes the two committed `.gen.nr` files.
//   - `./generate_interfaces.test.ts` — the CI freshness gate that re-renders from the
//     freshly-built artifacts and asserts byte-equality against the on-disk values.
//
// Why generated instead of hand-written: the function selectors in the wrappers (e.g.
// `consume((Field),Field)`) must stay in lockstep with the contracts' external function
// signatures. A drifted hand-coded string compiles fine but lands public calls at the
// wrong dispatcher entry. Driving the file from the artifact + a byte-equality test
// removes that whole failure mode.
import { decodeFunctionSignature } from '@aztec/stdlib/abi';
import type { ABIParameter, AbiType } from '@aztec/stdlib/abi';
import {
  AZTEC_ONLY_SELF_ATTRIBUTE,
  AZTEC_PUBLIC_ATTRIBUTE,
  AZTEC_VIEW_ATTRIBUTE,
  type NoirCompiledContract,
} from '@aztec/stdlib/noir';

import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const REPO_ROOT = path.resolve(__dirname, '../../../../');

export const AZTEC_NR_SRC_DIR = path.join(REPO_ROOT, 'noir-projects/aztec-nr/aztec/src');

export type InterfaceSpec = {
  /** Name of the generated struct + the canonical contract whose external surface it wraps. */
  interfaceName: string;
  /** Absolute path to the compiled artifact JSON. */
  artifactPath: string;
  /** Absolute path where the generated `.gen.nr` should be written. */
  outputPath: string;
  /** Relative path used in the generated file's header to point readers at this script. */
  generatorRelPath: string;
};

const NOIR_INTERNALS_PREFIX = '__aztec_nr_internals__';

export const AUTH_REGISTRY_INTERFACE: InterfaceSpec = {
  interfaceName: 'AuthRegistryInterface',
  artifactPath: path.join(REPO_ROOT, 'noir-projects/noir-contracts/target/auth_registry_contract-AuthRegistry.json'),
  outputPath: path.join(AZTEC_NR_SRC_DIR, 'authwit/auth_registry_interface.nr'),
  generatorRelPath: 'yarn-project/canonical-contracts/src/scripts/generate_interfaces.ts',
};

export const PUBLIC_CHECKS_INTERFACE: InterfaceSpec = {
  interfaceName: 'PublicChecksInterface',
  artifactPath: path.join(REPO_ROOT, 'noir-projects/noir-contracts/target/public_checks_contract-PublicChecks.json'),
  outputPath: path.join(AZTEC_NR_SRC_DIR, 'public_checks_interface.nr'),
  generatorRelPath: 'yarn-project/canonical-contracts/src/scripts/generate_interfaces.ts',
};

export const ALL_INTERFACES: InterfaceSpec[] = [AUTH_REGISTRY_INTERFACE, PUBLIC_CHECKS_INTERFACE];

/**
 * A single external public function on a canonical contract, narrowed to what the renderer needs.
 */
type ExternalFn = {
  /** External function name as it appears at the dispatcher (prefix stripped). */
  name: string;
  /** Whether the function is annotated `#[view]`. */
  isView: boolean;
  parameters: ABIParameter[];
  /** `null` if the function returns `()`; otherwise the single ABI return type. */
  returnType: AbiType | null;
};

/**
 * Extracts the externally-callable public functions from a compiled artifact. Skips the
 * synthesized `public_dispatch` entry; includes `#[only_self]` since it is still routable
 * via the dispatcher and we want the wrapper to expose every signature the dispatcher does.
 */
export function externalPublicFunctions(artifact: NoirCompiledContract): ExternalFn[] {
  const out: ExternalFn[] = [];
  for (const fn of artifact.functions) {
    if (!fn.custom_attributes.includes(AZTEC_PUBLIC_ATTRIBUTE)) {
      continue;
    }
    if (!fn.name.startsWith(NOIR_INTERNALS_PREFIX)) {
      // The macro-injected `public_dispatch` (and any other non-prefixed public function) is
      // not part of the user-facing surface.
      continue;
    }
    const name = fn.name.slice(NOIR_INTERNALS_PREFIX.length);
    out.push({
      name,
      isView: fn.custom_attributes.includes(AZTEC_VIEW_ATTRIBUTE),
      parameters: fn.abi.parameters,
      returnType: fn.abi.return_type?.abi_type ?? null,
    });
  }
  // Sort by name for deterministic output regardless of artifact ordering.
  out.sort((a, b) => a.name.localeCompare(b.name));
  return out;
}

/**
 * Maps an ABI type to the Noir type name to use in the generated method signature.
 */
function noirTypeName(type: AbiType): string {
  switch (type.kind) {
    case 'field':
      return 'Field';
    case 'boolean':
      return 'bool';
    case 'integer':
      return type.sign === 'signed' ? `i${type.width}` : `u${type.width}`;
    case 'struct': {
      // Only `AztecAddress` is supported as a struct parameter today — the two canonical
      // contracts we wrap don't expose any other user-defined types at their external
      // boundary. Extend this if a new canonical contract needs more.
      if (type.path.endsWith('::AztecAddress')) {
        return 'AztecAddress';
      }
      throw new Error(`Unsupported struct type in generated interface: ${type.path}`);
    }
    default:
      throw new Error(`Unsupported parameter kind in generated interface: ${type.kind}`);
  }
}

/**
 * Maps an ABI type to the number of `Field`s it serializes into for the args array length.
 */
function serializedLen(type: AbiType): number {
  switch (type.kind) {
    case 'field':
    case 'boolean':
    case 'integer':
      return 1;
    case 'struct': {
      // Same as above: only `AztecAddress`, which serializes to one Field (its `inner`).
      if (type.path.endsWith('::AztecAddress')) {
        return 1;
      }
      throw new Error(`Unsupported struct type in generated interface: ${type.path}`);
    }
    default:
      throw new Error(`Unsupported parameter kind in generated interface: ${type.kind}`);
  }
}

/**
 * Renders the `[<expr>, <expr>, ...]` args array passed to `PublicCall::new`/`PublicStaticCall::new`.
 * Mirrors the cast pattern the hand-written stubs used (`x as Field` / `addr.to_field()`).
 */
function renderArgsArrayExpr(parameters: ABIParameter[]): string {
  if (parameters.length === 0) {
    return '[]';
  }
  const exprs = parameters.map(p => paramToFieldExpr(p.name, p.type));
  return `[${exprs.join(', ')}]`;
}

function paramToFieldExpr(name: string, type: AbiType): string {
  switch (type.kind) {
    case 'field':
      return name;
    case 'boolean':
    case 'integer':
      return `${name} as Field`;
    case 'struct':
      if (type.path.endsWith('::AztecAddress')) {
        return `${name}.to_field()`;
      }
      throw new Error(`Unsupported struct type in generated interface: ${type.path}`);
    default:
      throw new Error(`Unsupported parameter kind in generated interface: ${type.kind}`);
  }
}

/**
 * Renders the `PublicCall<M, N, R>` / `PublicStaticCall<M, N, R>` return type for a generated
 * interface method. Mirrors what the `#[aztec]` macro stub generator emits.
 */
function renderCallReturnType(fn: ExternalFn): string {
  const nameLen = Buffer.byteLength(fn.name, 'utf8');
  const argsLen = fn.parameters.reduce((acc, p) => acc + serializedLen(p.type), 0);
  const returnT = fn.returnType === null ? '()' : noirTypeName(fn.returnType);
  const callKind = fn.isView ? 'PublicStaticCall' : 'PublicCall';
  return `${callKind}<${nameLen}, ${argsLen}, ${returnT}>`;
}

/** nargo fmt's hard wrap width — must mirror `max_width` in `noir-projects/aztec-nr/noirfmt.toml`. */
const NARGO_FMT_MAX_WIDTH = 120;

function renderMethodSignature(fn: ExternalFn, returnType: string): string {
  const inlineParams = fn.parameters.map(p => `${p.name}: ${noirTypeName(p.type)}`).join(', ');
  const inlineSignature = `    pub fn ${fn.name}(self${
    inlineParams.length === 0 ? '' : ', ' + inlineParams
  }) -> ${returnType} {`;

  if (inlineSignature.length <= NARGO_FMT_MAX_WIDTH) {
    return inlineSignature;
  }

  // nargo fmt's wrap style places `self` and each parameter on its own line, with a trailing comma.
  const wrappedParamLines = ['        self', ...fn.parameters.map(p => `        ${p.name}: ${noirTypeName(p.type)}`)]
    .map(l => `${l},`)
    .join('\n');
  return [`    pub fn ${fn.name}(`, wrappedParamLines, `    ) -> ${returnType} {`].join('\n');
}

function renderMethod(fn: ExternalFn): string {
  const signature = decodeFunctionSignature(fn.name, fn.parameters);
  const returnType = renderCallReturnType(fn);
  const callKind = fn.isView ? 'PublicStaticCall' : 'PublicCall';
  const argsExpr = renderArgsArrayExpr(fn.parameters);

  const signatureLine = renderMethodSignature(fn, returnType);
  const selectorLine = `        let selector = comptime { FunctionSelector::from_signature("${signature}") };`;

  // Emit the `${callKind}::new(...)` body in multi-line form unconditionally. This matches the
  // style of the hand-written stub it is replacing and stays well within nargo fmt's 120-char
  // wrap width so the formatter does not touch the file after we write it.
  const constructorLines = [
    `        ${callKind}::new(`,
    `            self.target_contract,`,
    `            selector,`,
    `            "${fn.name}",`,
    `            ${argsExpr},`,
    `        )`,
  ];

  return [signatureLine, selectorLine, ...constructorLines, `    }`].join('\n');
}

/**
 * Determines which `PublicCall` / `PublicStaticCall` types need to be imported.
 */
function neededCallImports(fns: ExternalFn[]): string[] {
  const needs = new Set<string>();
  for (const fn of fns) {
    needs.add(fn.isView ? 'PublicStaticCall' : 'PublicCall');
  }
  return Array.from(needs).sort();
}

/**
 * Renders the full generated `.gen.nr` file for an interface, byte-for-byte.
 *
 * The output is intentionally pre-wrapped (no lines >120 chars in the generated header /
 * struct, and the method bodies are short) so `nargo fmt --check` does not perturb the file
 * after the renderer writes it. The freshness gate compares this output byte-for-byte to
 * what is committed on disk.
 */
export function renderInterfaceFile(spec: InterfaceSpec, artifact: NoirCompiledContract): string {
  const fns = externalPublicFunctions(artifact);
  if (fns.length === 0) {
    throw new Error(`No external public functions found in ${spec.artifactPath}`);
  }

  const callImports = neededCallImports(fns);
  const callImportLine =
    callImports.length === 1
      ? `use crate::context::calls::${callImports[0]};`
      : `use crate::context::calls::{${callImports.join(', ')}};`;

  // `ToField` is only used when an `AztecAddress` parameter is rendered as `addr.to_field()`.
  // Pull it in conditionally so we don't trip nargo's unused-import warning for the simpler
  // interfaces (e.g. PublicChecks, which only takes primitive parameters).
  const usesAddressParam = fns.some(fn =>
    fn.parameters.some(p => p.type.kind === 'struct' && p.type.path.endsWith('::AztecAddress')),
  );
  const protocolImportItems = ['abis::function_selector::FunctionSelector', 'address::AztecAddress'];
  if (usesAddressParam) {
    protocolImportItems.push('traits::ToField');
  }
  const protocolImportLine = `use crate::protocol::{${protocolImportItems.join(', ')}};`;

  const methods = fns.map(renderMethod).join('\n\n');

  return `// GENERATED FILE - DO NOT EDIT
//
// Written by \`${spec.generatorRelPath}\` from the compiled
// \`${artifact.name}\` artifact. Regenerate with
// \`yarn workspace @aztec/canonical-contracts run regen:canonical-interfaces\`.
//
// The selectors below are derived via \`comptime { FunctionSelector::from_signature(...) }\` at
// Noir compile time, with the signature string emitted from the artifact's parameter list. This
// keeps the wrapper in lockstep with whatever the \`#[aztec]\` macro generates for the real
// contract; any drift between the contract's external signatures and this file fails the
// \`generate_interfaces.test.ts\` freshness gate.

${callImportLine}
${protocolImportLine}

pub struct ${spec.interfaceName} {
    pub target_contract: AztecAddress,
}

impl ${spec.interfaceName} {
    pub fn at(target_contract: AztecAddress) -> Self {
        Self { target_contract }
    }

${methods}
}
`;
}
